n = int(input())
q_s = list(map(int, input().split()))
a_s = list(map(int, input().split()))
b_s = list(map(int, input().split()))


max_num = 0
for i in range(10**6 + 1):
    number_of_a = i
    min_number_of_b = float('inf')
    for j in range(n):
        if a_s[j] * number_of_a > q_s[j]:
            min_number_of_b = -1
            break
        if b_s[j] != 0:
            number_of_b = (q_s[j] - a_s[j] * number_of_a) // b_s[j]
            min_number_of_b = min(min_number_of_b, number_of_b)
        else:
            min_number_of_b = min(min_number_of_b, float('inf'))
    if min_number_of_b >= 0:
        max_num = max(max_num, number_of_a + min_number_of_b)
print(max_num)
